{"provenance":"deterministic","nodes":[{"name":"SanitizeInstance","kind":"function","path":"entityid/entityid.go","lines":[318,347],"body":"func SanitizeInstance(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		if isAllowedInstanceRune(r) {
			b.WriteRune(r)
		} else {
			b.WriteRune('-')
		}
	}
	out := b.String()
	for strings.Contains(out, "--") {
		out = strings.ReplaceAll(out, "--", "-")
	}
	out = strings.TrimFunc(out, func(r rune) bool { return !isASCIIAlnum(r) })

	if out == "" {
		return shortHash(s)
	}
	if len(out) > maxInstanceLen {
		suffix := shortHash(s)
		prefix := strings.TrimRightFunc(out[:maxInstanceLen-len(suffix)-1],
			func(r rune) bool { return !isASCIIAlnum(r) })
		if prefix == "" {
			return suffix
		}
		return prefix + "-" + suffix
	}
	return out
}","relations":{"callee":[{"name":"isASCIIAlnum","path":"entityid/entityid.go","line":387},{"name":"isAllowedInstanceRune","path":"entityid/entityid.go","line":383},{"name":"shortHash","path":"entityid/entityid.go","line":391}],"caller":[{"name":"TestSanitizeInstance","path":"entityid/entityid_test.go","line":255},{"name":"TestSanitizeInstance_DeterministicForSameInput","path":"entityid/entityid_test.go","line":304},{"name":"TestSanitizeInstance_FallbackHash","path":"entityid/entityid_test.go","line":292},{"name":"TestSanitizeInstance_LengthCapPreservesUniqueness","path":"entityid/entityid_test.go","line":313},{"name":"DocumentEntityID","path":"handler/doc/entities.go","line":85},{"name":"chunkInstance","path":"handler/doc/entities.go","line":139},{"name":"BuildAuthorEntity","path":"handler/git/entities.go","line":37},{"name":"BuildBranchEntity","path":"handler/git/entities.go","line":57},{"name":"newAuthorEntity","path":"handler/git/entities.go","line":171},{"name":"newBranchEntity","path":"handler/git/entities.go","line":213},{"name":"Triples","path":"handler/git/entities.go","line":113}],"container":[{"name":"entityid.go","path":"entityid/entityid.go","line":1}]},"class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-f25674.workspace.golang.function.entityid-entityid-go-SanitizeInstance"}],"truncated":false,"contract_version":"2"}

{"provenance":"deterministic","nodes":[{"name":"decideLifecycleActions","kind":"function","path":"processor/supersession/lifecycle.go","lines":[199,268],"body":"func decideLifecycleActions(inScope []gtypes.EntityState, reason string, stat func(path string) bool) (toMark []message.Triple, toClear []string, pathCount int) {
	if stat == nil {
		// Nothing to check liveness against — the source itself is gone, so
		// every in-scope entity is unconditionally stale.
		for i := range inScope {
			if isMarkedStale(inScope[i].Triples) {
				continue
			}
			toMark = append(toMark, staleTriple(inScope[i].ID, reason))
		}
		return toMark, toClear, 0
	}

	parentCounts := make(map[string]int)
	for _, entity := range inScope {
		if n, ok := tripleInt(entity.Triples, source.DocChunkCount); ok && n >= 0 {
			parentCounts[entity.ID] = n
		}
	}
	byPath := make(map[string][]gtypes.EntityState)
	for i := range inScope {
		p, ok := pathOf(inScope[i].Triples)
		if !ok {
			continue // no path predicate — can't determine liveness
		}
		byPath[p] = append(byPath[p], inScope[i])
	}
	pathCount = len(byPath)

	for path, group := range byPath {
		present := stat(path)
		if !present {
			for i := range group {
				if !isMarkedStale(group[i].Triples) {
					toMark = append(toMark, staleTriple(group[i].ID, reason))
				}
			}
			continue
		}
		// The file is present, but a document that SHRANK leaves passages
		// behind that no filesystem check can see: every passage of a
		// ten-passage document that is now seven passages long still carries
		// the path of a file that is very much still there. The parent's
		// DocChunkCount is the only evidence, so liveness for a passage is
		// index < count rather than stat().
		for i := range group {
			if isSourceRemoved(group[i].Triples) {
				continue
			}
			liveCount, haveCount := passageParentCount(group[i], parentCounts)
			marked := isMarkedStale(group[i].Triples)
			vanished := haveCount && isVanishedPassage(group[i].Triples, liveCount)
			switch {
			case vanished && !marked:
				toMark = append(toMark, staleTriple(group[i].ID, graph.LifecycleReasonPassageRemoved))
			case !vanished && marked:
				// Without the parent's count there is no evidence either way, so
				// clearing a passage's marker here would resurrect a genuinely
				// vanished passage whenever enumeration truncated before its
				// parent — and re-mark it on the next full pass. Absence of
				// evidence must not read as evidence of liveness.
				if !haveCount && isPassage(group[i].Triples) {
					continue
				}
				toClear = append(toClear, group[i].ID)
			}
		}
	}
	return toMark, toClear, pathCount
}","relations":{"callee":[{"name":"isMarkedStale","path":"processor/supersession/lifecycle.go","line":352},{"name":"isPassage","path":"processor/supersession/lifecycle.go","line":302},{"name":"isSourceRemoved","path":"processor/supersession/lifecycle.go","line":291},{"name":"isVanishedPassage","path":"processor/supersession/lifecycle.go","line":311},{"name":"passageParentCount","path":"processor/supersession/lifecycle.go","line":272},{"name":"pathOf","path":"processor/supersession/lifecycle.go","line":363},{"name":"staleTriple","path":"processor/supersession/lifecycle.go","line":374},{"name":"tripleInt","path":"processor/supersession/lifecycle.go","line":320}],"caller":[{"name":"TestAbsentSet_LeavesPresentObjectsAlone","path":"processor/supersession/lifecycle_absent_test.go","line":125},{"name":"TestAbsentSet_MarksParentAndPassagesTogether","path":"processor/supersession/lifecycle_absent_test.go","line":91},{"name":"TestAbsentSet_ReappearedArtifactIsCleared","path":"processor/supersession/lifecycle_absent_test.go","line":167},{"name":"TestDecideLifecycleActions_AllPassagesLive_NoAction","path":"processor/supersession/lifecycle_passage_test.go","line":272},{"name":"TestDecideLifecycleActions_CodeEntitiesUnaffectedByPassageRules","path":"processor/supersession/lifecycle_passage_test.go","line":394},{"name":"TestDecideLifecycleActions_DeletedFile_MarksParentAndEveryPassage","path":"processor/supersession/lifecycle_passage_test.go","line":310},{"name":"TestDecideLifecycleActions_NumericTriplesSurviveJSONRoundTrip","path":"processor/supersession/lifecycle_passage_test.go","line":430},{"name":"TestDecideLifecycleActions_PassagesWithoutParent_NeverMarked","path":"processor/supersession/lifecycle_passage_test.go","line":333},{"name":"TestDecideLifecycleActions_PreChunkingDocument_BehavesAsBefore","path":"processor/supersession/lifecycle_passage_test.go","line":358},{"name":"TestDecideLifecycleActions_RegrownDocument_ClearsRevivedPassages","path":"processor/supersession/life