	// The document is marked stale from an earlier pass, and its passages
	// with it.
	fx := docFixture{
		path:       "reports/q4.md",
		count:      2,
		passages:   2,
		markedIdx:  []int{0, 1},
		parentMark: true,
	}

	// The bucket now holds it again, so the completed pass names something
	// else as absent — or nothing at all.
	stat, err := livenessOracle(graph.LifecycleRunRequest{Owner: "owner-a",
		Org:     "acme",
		Systems: []string{"s"},
		Absent:  []string{"reports/some-other-doc.md"},
	})
	if err != nil {
		t.Fatalf("livenessOracle: %v", err)
	}

	toMark, toClear, _ := decideLifecycleActions(fx.build(), graph.LifecycleReasonFileDeleted, stat)

	if len(toMark) != 0 {
		t.Errorf("marked %d entities for a document that is present", len(toMark))
	}
	if len(toClear) != 3 {
		t.Fatalf("cleared %v, want the parent and both passages", toClear)
	}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-f25674.workspace.golang.function.processor-supersession-lifecycle_absent_test-go-TestAbsentSet_ReappearedArtifactIsCleared"},{"name":"TestLivenessOracle_AbsentSetAnswersLiveness","kind":"function","path":"processor/supersession/lifecycle_absent_test.go","lines":[41,63],"body":"func TestLivenessOracle_AbsentSetAnswersLiveness(t *testing.T) {
	stat, err := livenessOracle(graph.LifecycleRunRequest{Owner: "owner-a",
		Org:     "acme",
		Systems: []string{"s"},
		Absent:  []string{"reports/q4.md", "reports/old.md"},
	})
	if err != nil {
		t.Fatalf("livenessOracle: %v", err)
	}
	if stat == nil {
		t.Fatal("an absent set must yield an oracle")
	}

	if stat("reports/q4.md") {
		t.Error("a named path must read as gone")
	}
	// Anything the caller did not name is present. That is what lets an
	// artifact which came back clear its marker on this same pass instead of
	// waiting for a re-seed.
	if !stat("reports/q3.md") {
		t.Error("a path the caller did not name must read as present")
	}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-f25674.workspace.golang.function.processor-supersession-lifecycle_absent_test-go-TestLivenessOracle_AbsentSetAnswersLiveness"},{"name":"TestIntegration_StalenessLifecycle","kind":"function","path":"internal/governance/staleness_lifecycle_integration_test.go","lines":[50,228],"body":"func TestIntegration_StalenessLifecycle(t *testing.T) {
	ctx := context.Background()
	tc := natstest.New(t,
		natstest.WithJetStream(),
		natstest.WithStreams(natstest.Stream{
			Name:     "GRAPH",
			Subjects: []string{"graph.ingest.entity"},
		}),
	)
	if _, err := BootstrapStandalone(nil); err != nil {
		t.Fatalf("BootstrapStandalone() error = %v", err)
	}

	reg := payloadregistry.New()
	if err := semsourcegraph.RegisterPayloads(reg); err != nil {
		t.Fatalf("RegisterPayloads() error = %v", err)
	}
