{"provenance":"embedding","nodes":[{"name":"putBody","kind":"function","path":"handler/doc/entities.go","lines":[403,425],"body":"func putBody(ctx context.Context, store storage.Store, instance, body, mimeType string) (string, *message.StorageReference, error) {
	if store == nil || instance == "" {
		return "", nil, ErrBodyStoreRequired
	}
	if body == "" {
		return "", nil, nil
	}
	sum := sha256.Sum256([]byte(body))
	key := "doc:" + hex.EncodeToString(sum[:])
	if err := store.Put(ctx, key, []byte(body)); err != nil {
		// Classified as deployment-level, not per-document. A store that cannot
		// be written to will fail identically for every following document, and
		// falling through to the walk's skip branch would drop each one whole —
		// parent included — while reporting a healthy ingest.
		return "", nil, fmt.Errorf("%w: store passage body: %w", ErrBodyStoreRequired, err)
	}
	return key, &message.StorageReference{
		StorageInstance: instance,
		Key:             key,
		ContentType:     mimeType,
		Size:            int64(len(body)),
	}, nil
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-f25674.workspace.golang.function.handler-doc-entities-go-putBody"},{"name":"BodyStoreBucket","kind":"const","path":"graph/bodystore.go","lines":[17,17],"body":"	BodyStoreBucket = "CONTENT"","class":"https://www.commoncoreontologies.org/ont00000965","handle":"c360.semsource-f25674.workspace.golang.const.graph-bodystore-go-BodyStoreBucket"},{"name":"codeBody","kind":"struct","path":"processor/ast-source/bodystore.go","lines":[71,74],"body":"type codeBody struct {
