	store := bodyOffloadStore(t)
	ctx := context.Background()
	body := []byte("func f() { return 1 }")
	key := bodyKeyPrefix + hashBody(string(body))

	if err := store.Put(ctx, key, body); err != nil {
		t.Fatalf("first put: %v", err)
	}
	first, err := store.Get(ctx, key)
	if err != nil {
		t.Fatalf("get: %v", err)
	}

	if err := store.Put(ctx, key, body); err != nil {
		t.Fatalf("second put: %v", err)
	}
	second, err := store.Get(ctx, key)
	if err != nil {
		t.Fatalf("get: %v", err)
	}

	if string(first) != string(second) {
		t.Fatal("content-addressed key returned different bytes; the dedup premise is wrong")
	}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-f25674.workspace.golang.function.processor-ast-source-bodystore_bench_integration_test-go-TestIntegration_DuplicateBodyPutIsRedundant"},{"name":"CodeBodyStore","kind":"const","path":"source/ast/predicates.go","lines":[77,77],"body":"	CodeBodyStore = "code.body.store" // storage component instance name (e.g. "objectstore")","class":"https://www.commoncoreontologies.org/ont00000965","handle":"c360.semsource-f25674.workspace.golang.const.source-ast-predicates-go-CodeBodyStore"}],"truncated":true,"contract_version":"2"}

