{"provenance":"deterministic","nodes":[{"name":"URLToSlug","kind":"function","path":"workspace/workspace.go","lines":[162,182],"body":"func URLToSlug(rawURL string) string {
	// Handle SSH shorthand: git@github.com:owner/repo.git → github.com/owner/repo.git
	if strings.HasPrefix(rawURL, "git@") {
		rawURL = strings.TrimPrefix(rawURL, "git@")
		rawURL = strings.Replace(rawURL, ":", "/", 1)
	}

	// Strip .git suffix before any further processing so it is removed
	// regardless of which parse path we take below.
	rawURL = strings.TrimSuffix(rawURL, ".git")

	// Parse as URL to extract host + path.
	parsed, err := url.Parse(rawURL)
	if err != nil || parsed.Host == "" {
		// Fallback: just slugify the whole string.
		return slugify(rawURL)
	}

	combined := parsed.Host + parsed.Path
	return slugify(combined)
}","relations":{"callee":[{"name":"slugify","path":"workspace/workspace.go","line":468}],"caller":[{"name":"startSubmoduleWatchers","path":"cmd/semsource/run.go","line":1089},{"name":"expandMultiBranch","path":"config/expand.go","line":154},{"name":"expandSingleBranch","path":"config/expand.go","line":92},{"name":"TestTick_ExpandsDualPinWithCanonicalIdentityAndScopedInstances","path":"internal/subwatch/subwatch_test.go","line":116},{"name":"EnsureRepo","path":"workspace/workspace.go","line":36},{"name":"TestURLToSlug","path":"workspace/workspace_test.go","line":12},{"name":"systemSlug","path":"handler/git/handler.go","line":398},{"name":"Tick","path":"internal/subwatch/subwatch.go","line":123},{"name":"spawn","path":"internal/subwatch/subwatch.go","line":202}],"container":[{"name":"workspace.go","path":"workspace/workspace.go","line":1}]},"class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-f25674.workspace.golang.function.workspace-workspace-go-URLToSlug"}],"impact":{"nodes":88,"files":28,"truncated":false},"truncated":false,"contract_version":"2"}

{"provenance":"embedding","nodes":[{"name":"SystemSlug","kind":"function","path":"entityid/entityid.go","lines":[132,179],"body":"func SystemSlug(canonicalPath string) string {
	// Strip URL scheme if present so "https://host/path" becomes "host/path".
	if parsed, err := url.Parse(canonicalPath); err == nil && parsed.Host != "" {
		canonicalPath = parsed.Host + parsed.Path
	}
	canonicalPath = strings.TrimSuffix(canonicalPath, ".git")
	canonicalPath = strings.TrimPrefix(canonicalPath, "./")

	// For absolute filesystem paths, use only the base name. Workspace-
	// cloned repos already have a meaningful slug as their directory name
	// (e.g. "github-com-opensensorhub-osh-core"), so the parent hierarchy
	// (temp dirs, user home, etc.) is noise that inflates entity IDs.
	if filepath.IsAbs(canonicalPath) {
		canonicalPath = filepath.Base(canonicalPath)
	}

	// Map any character outside the entity-ID allowlist ([A-Za-z0-9_-]) to a
	// hyphen. This is an ALLOWLIST, not a denylist: a denylist (only /,:,.) let
	// '@' through from Go module-cache paths (e.g. "semstreams@v1.2.3"), which
	// produced invalid NATS KV keys and failed component-name validation. Dots
	// break the 6-part ID's segment separator, so they map here too.
	var b strings.Builder
	b.Grow(len(canonicalPath))
	for _, r := range canonicalPath {
		if isAllowedInstanceRune(r) {
			b.WriteRune(r)
		} else {
			b.WriteRune('-')
		}
	}
	slug := b.String()
	for strings.Contains(slug, "--") {
		slug = strings.ReplaceAll(slug, "--", "-")
	}
	// Trim to an alphanumeric boundary so the slug is a valid ID segment
	// (^[A-Za-z0-9]…): a leading/trailing '-' or '_' would violate it.
	slug = strings.TrimFunc(slug, func(r rune) bool { return !isASCIIAlnum(r) })

	// Safety cap: truncate and append a short content hash when the slug
	// still exceeds the limit (e.g. extremely long directory names).
	if len(slug) > maxSystemSlugLen {
		h := sha256.Sum256([]byte(slug))
		suffix := hex.EncodeToString(h[:3]) // 6 hex chars
		slug = slug[:maxSystemSlugLen-7] + "-" + suffix
	}

	return slug
