	root := t.TempDir()
	write := func(rel, src string) {
		t.Helper()
		if err := os.WriteFile(filepath.Join(root, rel), []byte(src), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("a.go", "package p\nfunc Alpha() {}\n")
	write("b.go", "package p\ntype M struct{}\nfunc (M) Beta() {}\n")
	write("c_test.go", "package p\nfunc TestOnly() {}\n")

	p := NewParser(testAuthority("acme"), "proj", root)
	funcs := p.packageFuncs(".")
	if funcs["Alpha"] != "a.go" {
		t.Errorf("funcs[Alpha] = %q, want a.go", funcs["Alpha"])
	}
	if _, ok := funcs["Beta"]; ok {
		t.Error("method Beta harvested as a package-level func")
	}
	if _, ok := funcs["TestOnly"]; ok {
		t.Error("_test.go func harvested")
	}

	// A sibling edit (size change) must invalidate the cached scan.
	write("b.go", "package p\ntype M struct{}\nfunc (M) Beta() {}\nfunc Gamma() {}\n")
	if got := p.packageFuncs(".")["Gamma"]; got != "b.go" {
		t.Errorf("after sibling edit, funcs[Gamma] = %q, want b.go", got)
	}
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-f25674.workspace.golang.function.source-ast-golang-call_resolution_test-go-TestPackageScan_FuncsHarvested"},{"name":"packageScan","kind":"method","path":"source/ast/golang/imports.go","lines":[61,128],"body":"func (p *Parser) packageScan(dir string) pkgTypesEntry {
	absDir := filepath.Join(p.repoRoot, dir)
	entries, err := os.ReadDir(absDir)
	if err != nil {
		return pkgTypesEntry{}
	}

	var goFiles []os.DirEntry
	var sig strings.Builder
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") || strings.HasSuffix(e.Name(), "_test.go") {
			continue
		}
		goFiles = append(goFiles, e)
		if info, ierr := e.Info(); ierr == nil {
			fmt.Fprintf(&sig, "%s:%d:%d;", e.Name(), info.Size(), info.ModTime().UnixNano())
		}
	}

	if p.pkgTypesCache == nil {
		p.pkgTypesCache = make(map[string]pkgTypesEntry)
	}
	if cached, ok := p.pkgTypesCache[dir]; ok && cached.sig == sig.String() {
		return cached
	}

	types := make(map[string]goLocalType)
	funcs := make(map[string]string)
	fset := token.NewFileSet()
	for _, e := range goFiles {
		abs := filepath.Join(absDir, e.Name())
		f, perr := parser.ParseFile(fset, abs, nil, parser.SkipObjectResolution)
		if perr != nil {
			continue
		}
		rel, rerr := filepath.Rel(p.repoRoot, abs)
		if rerr != nil {
			rel = abs
		}
		for _, decl := range f.Decls {
			switch d := decl.(type) {
			case *goast.GenDecl:
				if d.Tok != token.TYPE {
					continue
				}
				for _, spec := range d.Specs {
					ts, ok := spec.(*goast.TypeSpec)
					if !ok {
						continue
					}
					if _, exists := types[ts.Name.Name]; !exists {
						types[ts.Name.Name] = goLocalType{relPath: rel, kind: goTypeKind(ts.Type)}
					}
				}
			case *goast.FuncDecl:
				if d.Recv != nil || d.Name == nil {
					continue
				}
				if _, exists := funcs[d.Name.Name]; !exists {
					funcs[d.Name.Name] = rel
				}
			}
		}
	}
	entry := pkgTypesEntry{sig: sig.String(), types: types, funcs: funcs}
	p.pkgTypesCache[dir] = entry
	return entry
}","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-f25674.workspace.golang.method.source-ast-golang-imports-go-Parser-packageScan"},{"name":"TestComponent_StatusDuringSlowSeed","kind":"function","path":"processor/source-manifest/status_slowseed_test.go","lines":[64,89],"body":"func TestComponent_StatusDuringSlowSeed(t *testing.T) {
